const { chromium } = await import('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage();
await page.goto('https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Array', { waitUntil: 'domcontentloaded', timeout: 30000 });
const text = await page.evaluate(() => document.body.innerText);
const title = await page.title();
await browser.close();
nodeRepl.write(JSON.stringify({title, length: text.length, last50: text.slice(-50), first120: text.slice(0,120)}, null, 2));
